node --input-type=module -e "
import { convert } from './ocr-numbers.js';
const badHeight = ' _ \n| |\n|_|';        // 3 rows, not multiple of 4
const badWidth  = ' _ \n| |\n|_|\n   x'; // 4 rows, width 4 not multiple of 3
try { convert(badHeight); console.log('height: NO ERROR (bad)'); }
catch (e) { console.log('height error:', e.message); }
try { convert(badWidth); console.log('width: NO ERROR (bad)'); }
catch (e) { console.log('width error:', e.message); }
console.log('single 0:', convert(' _ \n| |\n|_|\n   '));
"
